package com.shopsphere;import java.nio.charset.StandardCharsets;import java.util.*;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.web.SecurityFilterChain;
@Configuration class ProductConfig{@Bean JwtDecoder decoder(@Value("${shopsphere.jwt.secret}")String s){var k=new SecretKeySpec(Arrays.copyOf(s.getBytes(StandardCharsets.UTF_8),32),"HmacSHA256");return NimbusJwtDecoder.withSecretKey(k).macAlgorithm(org.springframework.security.oauth2.jose.jws.MacAlgorithm.HS256).build();}@Bean SecurityFilterChain security(HttpSecurity h)throws Exception{JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(jwt->List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+jwt.getClaimAsString("role"))));return h.csrf(x->x.disable()).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.GET,"/api/products","/api/products/**").permitAll().requestMatchers("/actuator/health","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().anyRequest().hasRole("ADMIN")).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(c))).build();}}
